<?php
declare(strict_types=1);$active_module='settlements';require_once __DIR__.'/layout.php';$u=$supplier_user;$q=db()->prepare('SELECT * FROM supplier_settlements WHERE supplier_id=? ORDER BY created_at DESC LIMIT 200');$q->execute([$u['supplier_id']]);$rows=$q->fetchAll();$totals=['pending'=>0,'paid'=>0];foreach($rows as $r)if(isset($totals[$r['status']]))$totals[$r['status']]+=(float)$r['net_amount'];supply_start('Tahsilat & mutabakat',$active_module);?><section class="page-intro"><p>Acente, API ve ödeme sağlayıcılarından oluşan net tahsilatlarınızı takip edin.</p></section><section class="stat-grid"><article><span>BEKLEYEN</span><b><?=number_format($totals['pending'],2)?> EUR</b></article><article><span>ÖDENEN</span><b><?=number_format($totals['paid'],2)?> EUR</b></article></section><section class="next-module"><h2>Mutabakat hareketleri</h2><?php if(!$rows):?><p>Henüz mutabakat hareketi yok. Onaylanan rezervasyonlar ve ödeme akışları burada net komisyon hesabıyla oluşur.</p><?php endif;?><?php foreach($rows as $r):?><p><b><?=htmlspecialchars($r['transaction_type'])?></b> · net <?=number_format((float)$r['net_amount'],2)?> <?=htmlspecialchars($r['currency'])?> · komisyon <?=number_format((float)$r['commission_amount'],2)?> · <?=htmlspecialchars($r['status'])?></p><?php endforeach;?></section><?php supply_end(); ?>
